import sys
from collections import defaultdict

MOD = 10**9 + 7
sys.setrecursionlimit(10**6)

def dfs(v, p, A, G, vis):
    vis[v] += 1
    for j in range(1, A[v] + 1):
        for u in G[v]:
            if u != p:
                dfs(u, v, A, G, vis)

def main():
    input = sys.stdin.readline
    N, Q = map(int, input().split())
    G = defaultdict(list)
    for _ in range(N - 1):
        u, v = map(int, input().split())
        G[u].append(v)
        G[v].append(u)

    A = list(map(int, input().split()))
    queries = [input().split() for _ in range(Q)]

    for query in queries:
        if query[0] == '1':
            v, x = int(query[1]), int(query[2])
            A[v - 1] = x
        else:
            v = int(query[1])
            vis = [0] * (N + 1)
            dfs(v, -1, A, G, vis)
            result = sum(vis[1:]) % MOD
            print(result)

if __name__ == "__main__":
    main()
